import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { ChildProcess, spawn } from 'node:child_process';
import type * as ChildProcessModule from 'node:child_process';
import type { Stats } from 'node:fs';
import { stat } from 'node:fs/promises';
import type * as FsModule from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { PassThrough } from 'node:stream';
import { fileURLToPath } from 'node:url';
import { HarnessOptionsSchema } from '@graphgoblin/contracts';
import type { HarnessEvent } from '@graphgoblin/engine';
import { killTree } from '../process/index.js';
import { ClaudeHarnessError } from './errors.js';
import { ClaudeHarness } from './harness.js';
import { runClaudeProcess } from './process.js';

vi.mock('node:child_process', async (importOriginal) => {
  const actual = await importOriginal<typeof ChildProcessModule>();
  return { ...actual, spawn: vi.fn() };
});
vi.mock('node:fs/promises', async (importOriginal) => {
  const actual = await importOriginal<typeof FsModule>();
  return { ...actual, stat: vi.fn() };
});
vi.mock('../process/index.js', () => ({ killTree: vi.fn() }));
let child: ChildProcess;
const scriptedChildren: ChildProcess[] = [];
const stdout = () => child.stdout;
const request = (signal = new AbortController().signal) => ({
  binary: 'synthetic-cli',
  args: [],
  cwd: 'synthetic-workspace',
  env: {},
  signal,
  timeoutMs: 1000,
  maxOutputBytes: 1024,
});
let directoryStats: Stats, fileStats: Stats;
beforeAll(async () => {
  const actual = await vi.importActual<typeof FsModule>('node:fs/promises');
  directoryStats = await actual.stat(tmpdir());
  fileStats = await actual.stat(fileURLToPath(import.meta.url));
});
beforeEach(() => {
  vi.useFakeTimers();
  vi.mocked(killTree).mockResolvedValue(true);
  vi.mocked(stat).mockResolvedValue(directoryStats);
  child = new ChildProcess();
  // These cases model a process that started; spawn refusals clear the pid as Node leaves it.
  Object.assign(child, { pid: 4242 });
  child.stdin = new PassThrough();
  child.stdout = new PassThrough();
  child.stderr = new PassThrough();
  vi.mocked(spawn).mockReturnValue(child);
});
afterEach(() => {
  for (const owned of [child, ...scriptedChildren.splice(0)]) {
    owned.stdin?.destroy();
    owned.stdout?.destroy();
    owned.stderr?.destroy();
  }
  vi.useRealTimers();
  vi.clearAllMocks();
});
describe('bounded native transport failure outcomes', () => {
  it.each(['abort', 'timeout'] as const)(
    'reports unconfirmed termination after %s instead of successful cancellation',
    async (mode) => {
      const controller = new AbortController();
      const result = runClaudeProcess(request(controller.signal));
      if (mode === 'abort') controller.abort();
      else await vi.advanceTimersByTimeAsync(1000);
      expect(killTree).toHaveBeenCalledWith(child);
      await vi.advanceTimersByTimeAsync(5000);
      expect(await result).toMatchObject({
        exitCode: null,
        terminationUnconfirmed: true,
        aborted: mode === 'abort',
        timedOut: mode === 'timeout',
      });
      child.emit('close', 0);
      expect(await result).toMatchObject({ terminationUnconfirmed: true });
    },
  );
  it('confirmed close clears the kill deadline and distinguishes normal cancellation', async () => {
    const controller = new AbortController();
    const result = runClaudeProcess(request(controller.signal));
    controller.abort();
    child.emit('close', null, 'SIGKILL');
    expect(await result).toMatchObject({ aborted: true, exitCode: null });
    expect(await result).not.toHaveProperty('terminationUnconfirmed');
    expect(vi.getTimerCount()).toBe(0);
  });
  it.each(['typed', 'unknown'] as const)(
    'retains only fixed %s parser diagnostics and kills the owned process',
    async (kind) => {
      const result = runClaudeProcess(request(), () => {
        if (kind === 'typed')
          throw new ClaudeHarnessError('HARNESS_PROTOCOL_ERROR', 'fixed parser diagnostic');
        throw new Error('PRIVATE_PROVIDER_BODY');
      });
      stdout()?.emit('data', Buffer.from('synthetic'));
      stdout()?.emit('data', Buffer.from('ignored'));
      expect(killTree).toHaveBeenCalledWith(child);
      child.emit('close', null);
      expect(await result).toMatchObject({ callbackError: { code: 'HARNESS_PROTOCOL_ERROR' } });
      expect(JSON.stringify(await result)).not.toContain('PRIVATE_PROVIDER_BODY');
    },
  );
  it('reports stdin delivery failure without claiming a successful turn', async () => {
    const result = runClaudeProcess(request());
    child.stdin?.emit('error', new Error('PRIVATE_STDIN_BODY'));
    expect(killTree).toHaveBeenCalledWith(child);
    child.emit('close', null);
    expect(await result).toMatchObject({ stdinFailed: true });
    expect(JSON.stringify(await result)).not.toContain('PRIVATE_STDIN_BODY');
  });
  it.each(['EACCES', 'EPERM'] as const)(
    'maps native spawn error %s without retaining its body',
    async (code) => {
      Object.assign(child, { pid: undefined });
      const result = runClaudeProcess(request());
      const error = Object.assign(new Error('PRIVATE_NATIVE_BODY'), { code });
      child.emit('error', error);
      expect(await result).toMatchObject({ spawnCode: code === 'EACCES' ? 'EACCES' : 'UNKNOWN' });
      expect(JSON.stringify(await result)).not.toContain('PRIVATE_NATIVE_BODY');
    },
  );
  it('does not treat a later error of a started child, such as a failed kill, as a spawn refusal', async () => {
    const result = runClaudeProcess(request());
    child.emit('error', Object.assign(new Error('PRIVATE_KILL_BODY'), { code: 'EPERM' }));
    child.emit('close', 0);
    const settled = await result;
    expect(settled).toMatchObject({ exitCode: 0 });
    expect(settled).not.toHaveProperty('spawnCode');
    expect(stat).not.toHaveBeenCalled();
  });
  it.each(['stdout', 'stderr'] as const)(
    "reports a started child's %s pipe failure and stops its tree",
    async (stream) => {
      const result = runClaudeProcess(request());
      child[stream]?.emit(
        'error',
        Object.assign(new Error('PRIVATE_PIPE_BODY'), { code: 'EPIPE' }),
      );
      expect(killTree).toHaveBeenCalledWith(child);
      child.emit('close', null);
      expect(await result).toMatchObject({ outputFailed: true, exitCode: null });
      expect(await result).not.toHaveProperty('spawnCode');
      expect(JSON.stringify(await result)).not.toContain('PRIVATE_PIPE_BODY');
    },
  );
});

describe('read-only observation after an actual spawn refusal (#364)', () => {
  const root = join(tmpdir(), 'gg-364-controlled');
  const executable = join(root, 'claude.exe');
  const workspace = join(root, 'workspace');
  // Windows process start also tries the path with `.com` and `.exe` appended.
  const names =
    process.platform === 'win32'
      ? [executable, `${executable}.com`, `${executable}.exe`]
      : [executable];
  const fault = (code?: string) =>
    Object.assign(new Error('PRIVATE_FS_BODY'), code === undefined ? {} : { code });
  // Tokens, because the case tables are built before the real Stats objects exist.
  type State = 'file' | 'directory' | Error | Promise<Stats>;
  function observe(states: Record<string, State>): void {
    vi.mocked(stat).mockImplementation((path) => {
      const state = states[String(path)];
      if (state === undefined) return Promise.reject(new Error(`unexpected ${String(path)}`));
      if (state instanceof Error) return Promise.reject(state);
      if (state === 'file') return Promise.resolve(fileStats);
      return state === 'directory' ? Promise.resolve(directoryStats) : state;
    });
  }
  const observed = () => vi.mocked(stat).mock.calls.map(([path]) => String(path));
  function refuse(
    code = 'ENOENT',
    binary = executable,
    signal?: AbortSignal,
    timeoutMs: number | null = 1000,
  ) {
    Object.assign(child, { pid: undefined });
    const result = runClaudeProcess({
      ...request(signal),
      binary,
      cwd: workspace,
      timeoutMs,
    });
    child.emit('error', Object.assign(new Error(`spawn ${binary} ${code}`), { code }));
    return result;
  }
  it('establishes a missing executable only when every name process start tries is absent or a folder', async () => {
    const absent = Object.fromEntries(names.map((name) => [name, fault('ENOENT')]));
    observe({ ...absent, [executable]: fault('ENOTDIR') });
    expect(await refuse()).toMatchObject({
      spawnCode: 'ENOENT',
      startRefusal: 'executable-missing',
    });
    expect(observed()).toEqual(names);
    observe({ ...absent, [executable]: 'directory' });
    expect(await refuse()).toMatchObject({ startRefusal: 'executable-missing' });
  });
  it.each([
    ['a file', 'file' as const],
    ['an unreadable path', fault('EACCES')],
    ['an unclassified read fault', fault()],
  ])('leaves the cause open when the executable path is %s', async (_case, state) => {
    observe({
      ...Object.fromEntries(names.map((name) => [name, fault('ENOENT')])),
      [executable]: state,
      [workspace]: 'directory',
    });
    const result = await refuse();
    expect(result).toMatchObject({ spawnCode: 'ENOENT', exitCode: null });
    expect(result).not.toHaveProperty('startRefusal');
    expect(observed()).toEqual([...names, workspace]);
    expect(JSON.stringify(result)).not.toContain('PRIVATE');
  });
  it.each([
    ['missing', fault('ENOENT'), 'working-directory-missing'],
    ['beneath a file', fault('ENOTDIR'), 'working-directory-missing'],
    ['a file', 'file', 'working-directory-not-directory'],
    ['an existing folder', 'directory', undefined],
    ['unreadable', fault('EACCES'), undefined],
    ['denied', fault('EPERM'), undefined],
  ] as const)(
    'classifies a working directory that is %s without resolving a bare executable name',
    async (_case, state, refusal) => {
      observe({ [workspace]: state });
      const result = await refuse('ENOENT', 'claude');
      expect(observed()).toEqual([workspace]);
      if (refusal) expect(result).toMatchObject({ spawnCode: 'ENOENT', startRefusal: refusal });
      else expect(result).not.toHaveProperty('startRefusal');
    },
  );
  it('never resolves a relative executable path', async () => {
    observe({ [workspace]: 'directory' });
    expect(await refuse('ENOENT', join('bin', 'claude.exe'))).not.toHaveProperty('startRefusal');
    expect(observed()).toEqual([workspace]);
  });
  it('establishes a missing executable only from an ENOENT refusal', async () => {
    observe({
      ...Object.fromEntries(names.map((name) => [name, fault('ENOENT')])),
      [workspace]: 'directory',
    });
    const result = await refuse('EACCES');
    expect(result).toMatchObject({ spawnCode: 'EACCES' });
    expect(result).not.toHaveProperty('startRefusal');
    expect(observed()).toEqual([workspace]);
  });
  it.each(['abort', 'deadline'] as const)(
    'reports the refusal at once without a diagnosis or timeout when the %s arrives during the observation',
    async (mode) => {
      let release!: (stats: Stats) => void;
      const pending = new Promise<Stats>((resolve) => {
        release = resolve;
      });
      observe({ ...Object.fromEntries(names.map((name) => [name, pending])), [workspace]: 'file' });
      const controller = new AbortController();
      const removed = vi.spyOn(controller.signal, 'removeEventListener');
      const result = refuse(
        'ENOENT',
        executable,
        controller.signal,
        mode === 'deadline' ? 15 : null,
      );
      expect(observed()).toEqual(names);
      if (mode === 'abort') controller.abort();
      else await vi.advanceTimersByTimeAsync(15);
      const settled = await result;
      expect(settled).toMatchObject({
        spawnCode: 'ENOENT',
        exitCode: null,
        aborted: mode === 'abort',
        timedOut: false,
      });
      expect(settled).not.toHaveProperty('startRefusal');
      expect(settled).not.toHaveProperty('terminationUnconfirmed');
      expect(killTree).not.toHaveBeenCalled();
      expect(removed).toHaveBeenCalledWith('abort', expect.any(Function));
      release(fileStats);
      await vi.advanceTimersByTimeAsync(0);
      expect(await result).toBe(settled);
      expect(observed()).toEqual(names);
      expect(vi.getTimerCount()).toBe(0);
    },
  );
  it.each(['success', 'rejection'] as const)(
    'bounds an unconfigured wait and ignores late metadata %s without a subsequent lookup',
    async (late) => {
      let release!: (stats: Stats) => void, reject!: (error: Error) => void;
      const pending = new Promise<Stats>((resolve, fail) => {
        release = resolve;
        reject = fail;
      });
      observe({ ...Object.fromEntries(names.map((name) => [name, pending])), [workspace]: 'file' });
      const controller = new AbortController();
      const removed = vi.spyOn(controller.signal, 'removeEventListener');
      const result = refuse('ENOENT', executable, controller.signal, null);
      child.emit('close', -4058);
      let settled = false;
      void result.then(() => {
        settled = true;
      });
      await vi.advanceTimersByTimeAsync(999);
      expect(settled).toBe(false);
      await vi.advanceTimersByTimeAsync(1);
      expect(settled).toBe(true);
      const value = await result;
      expect(value).toEqual({
        exitCode: null,
        stdout: '',
        timedOut: false,
        aborted: false,
        overflow: false,
        spawnCode: 'ENOENT',
      });
      const bytes = JSON.stringify(value);
      expect(removed).toHaveBeenCalledWith('abort', expect.any(Function));
      expect(vi.getTimerCount()).toBe(0);
      if (late === 'success') release(fileStats);
      else reject(fault('ENOENT'));
      await vi.advanceTimersByTimeAsync(0);
      expect(await result).toBe(value);
      expect(JSON.stringify(value)).toBe(bytes);
      expect(observed()).toEqual(names);
      expect(killTree).not.toHaveBeenCalled();
    },
  );
  it('starts the private budget at the refusal and retains timely factual metadata across wall-clock changes', async () => {
    let release!: (stats: Stats) => void;
    observe({
      [workspace]: new Promise<Stats>((resolve) => {
        release = resolve;
      }),
    });
    Object.assign(child, { pid: undefined });
    const result = runClaudeProcess({
      ...request(),
      binary: 'claude',
      cwd: workspace,
      timeoutMs: null,
    });
    await vi.advanceTimersByTimeAsync(2000);
    expect(stat).not.toHaveBeenCalled();
    expect(vi.getTimerCount()).toBe(0);
    child.emit('error', fault('ENOENT'));
    await vi.advanceTimersByTimeAsync(999);
    vi.setSystemTime(new Date('2099-01-01T00:00:00Z'));
    release(fileStats);
    expect(await result).toMatchObject({
      spawnCode: 'ENOENT',
      startRefusal: 'working-directory-not-directory',
      timedOut: false,
      aborted: false,
    });
    expect(vi.getTimerCount()).toBe(0);
  });
  it('rejects metadata after the absolute bound before a delayed timer callback can run', async () => {
    let now = 0,
      release!: (stats: Stats) => void;
    vi.spyOn(performance, 'now').mockImplementation(() => now);
    const pending = new Promise<Stats>((resolve) => {
      release = resolve;
    });
    observe({ ...Object.fromEntries(names.map((name) => [name, pending])), [workspace]: 'file' });
    const result = refuse('ENOENT', executable, undefined, null);
    now = 1000;
    release(fileStats);
    const value = await result;
    expect(value).toMatchObject({ spawnCode: 'ENOENT', timedOut: false, aborted: false });
    expect(value).not.toHaveProperty('startRefusal');
    expect(observed()).toEqual(names);
    expect(vi.getTimerCount()).toBe(0);
  });
  it('rechecks the monotonic deadline when the diagnostic timer fires early', async () => {
    let now = 0;
    vi.spyOn(performance, 'now').mockImplementation(() => now);
    observe({ [workspace]: new Promise<Stats>(() => undefined) });
    const result = refuse('EACCES', 'claude', undefined, null);
    let settled = false;
    void result.then(() => {
      settled = true;
    });
    await vi.advanceTimersByTimeAsync(1000);
    expect(settled).toBe(false);
    now = 1000;
    await vi.advanceTimersByTimeAsync(1000);
    expect(settled).toBe(true);
    expect(await result).toMatchObject({ spawnCode: 'EACCES', timedOut: false, aborted: false });
    expect(await result).not.toHaveProperty('startRefusal');
    expect(vi.getTimerCount()).toBe(0);
  });
  it('does not add a diagnostic deadline to an unbounded process that actually started', async () => {
    const result = runClaudeProcess({ ...request(), timeoutMs: null });
    let settled = false;
    void result.then(() => {
      settled = true;
    });
    await vi.advanceTimersByTimeAsync(5000);
    expect(settled).toBe(false);
    expect(vi.getTimerCount()).toBe(0);
    child.emit('close', 0);
    expect(await result).toMatchObject({ exitCode: 0, timedOut: false, aborted: false });
    expect(stat).not.toHaveBeenCalled();
    expect(killTree).not.toHaveBeenCalled();
  });
  it('ignores the pipe faults and close that follow a refusal, settling once with the refusal', async () => {
    observe({ [workspace]: 'directory' });
    const result = refuse('ENOENT', 'claude');
    // Windows reports a 260-character working directory like this (ENOTCONN on both pipes).
    for (const stream of ['stdout', 'stderr', 'stdin'] as const)
      child[stream]?.emit(
        'error',
        Object.assign(new Error('PRIVATE_PIPE_BODY'), { code: 'ENOTCONN' }),
      );
    child.emit('close', -4058);
    child.emit('error', Object.assign(new Error('PRIVATE_SECOND_BODY'), { code: 'EACCES' }));
    const settled = await result;
    expect(settled).toEqual({
      exitCode: null,
      stdout: '',
      timedOut: false,
      aborted: false,
      overflow: false,
      spawnCode: 'ENOENT',
    });
    expect(killTree).not.toHaveBeenCalled();
    expect(observed()).toEqual([workspace]);
  });
});

it.each(['stdout', 'stderr'] as const)(
  'classifies %s without mining model/turn content',
  async (stream) => {
    const result = runClaudeProcess({ ...request(), classifyDiagnostics: true });
    child[stream]?.emit(
      'data',
      Buffer.from(
        stream === 'stdout'
          ? 'A response discussing quota and authentication'
          : 'Usage limit: quota exhausted PRIVATE_BODY',
      ),
    );
    child.emit('close', 1);
    if (stream === 'stderr') expect(await result).toMatchObject({ failureState: 'quota' });
    else expect(await result).not.toHaveProperty('failureState');
    expect(JSON.stringify(await result)).not.toContain('PRIVATE_BODY');
  },
);

it('does not infer turn causes from stderr', async () => {
  const result = runClaudeProcess(request());
  child.stderr?.emit('data', Buffer.from('quota network authentication PRIVATE_BODY'));
  child.emit('close', 1);
  expect(await result).not.toHaveProperty('failureState');
  expect(JSON.stringify(await result)).not.toContain('PRIVATE_BODY');
});

it('reports nonzero tree acknowledgement even if the root independently closes', async () => {
  vi.mocked(killTree).mockResolvedValue(false);
  const controller = new AbortController();
  const pending = runClaudeProcess(request(controller.signal));
  controller.abort();
  child.emit('close', 0);
  expect(await pending).toMatchObject({ terminationUnconfirmed: true, exitCode: null });
});

it('completes cancellation when tree acknowledgement precedes child close', async () => {
  const controller = new AbortController();
  const pending = runClaudeProcess(request(controller.signal));
  controller.abort();
  await Promise.resolve();
  child.emit('close', null);
  expect(await pending).not.toHaveProperty('terminationUnconfirmed');
  expect(vi.getTimerCount()).toBe(0);
});

// Controlled child seam: the real runner and harness with scripted child processes. The pipe
// fault is an emitted stream error, not a native observation (#364).
describe('lost check output through the runner and harness (#364)', () => {
  const flags =
    '--safe-mode --restricted --setting-sources --strict-mcp-config --tools --allowedTools --permission-mode --permission-prompts --effort --json-schema --output-format --input-format --model --verbose --print --no-session-persistence --resume';
  const diagnosis = 'API Error: 401 PRIVATE_STDERR_BODY';
  /** Version and help pass; the sign-in check child follows the given script. */
  function scriptChecks(
    auth: (scripted: ChildProcess) => void,
    turn?: (scripted: ChildProcess) => void,
  ): void {
    vi.mocked(spawn).mockImplementation((_binary: string, args: readonly string[]) => {
      const scripted = new ChildProcess();
      scriptedChildren.push(scripted);
      Object.assign(scripted, { pid: 4243 });
      scripted.stdin = new PassThrough();
      scripted.stdout = new PassThrough();
      scripted.stderr = new PassThrough();
      // The runner attaches its listeners right after spawn returns; script the child after that.
      void Promise.resolve().then(() => {
        if (args.includes('auth')) {
          auth(scripted);
          return;
        }
        if (!args.includes('--version') && !args.includes('--help')) {
          turn?.(scripted);
          return;
        }
        scripted.stdout?.emit('data', Buffer.from(args.includes('--version') ? '2.1.285' : flags));
        scripted.emit('close', 0);
      });
      return scripted;
    });
  }
  it.each(['success', 'rejection'] as const)(
    'settles a default public turn after refused start despite pending stat and late %s',
    async (late) => {
      let release!: (stats: Stats) => void, reject!: (error: Error) => void, turnReady!: () => void;
      const metadata = new Promise<Stats>((resolve, fail) => {
        release = resolve;
        reject = fail;
      });
      const ready = new Promise<void>((resolve) => {
        turnReady = resolve;
      });
      vi.mocked(stat).mockReturnValue(metadata);
      scriptChecks(
        (scripted) => {
          scripted.stdout?.emit(
            'data',
            Buffer.from('{"authMethod":"claude.ai","email":"PRIVATE_ACCOUNT"}'),
          );
          scripted.emit('close', 0);
        },
        (scripted) => {
          Object.assign(scripted, { pid: undefined });
          scripted.emit(
            'error',
            Object.assign(new Error('PRIVATE_NATIVE_BODY'), { code: 'ENOENT' }),
          );
          scripted.emit('close', -4058);
          turnReady();
        },
      );
      const runner = vi.fn(runClaudeProcess);
      const controller = new AbortController();
      const session = new ClaudeHarness({
        platform: 'win32',
        binary: 'synthetic-cli',
        runner,
      }).start(
        {
          workingDirectory: 'synthetic-workspace',
          model: 'claude-opus-5-5',
          effort: 'xhigh',
          options: HarnessOptionsSchema.parse({ sandbox: 'read-only', approval: 'never' }),
          turn: { prompt: 'PRIVATE_PROMPT' },
        },
        controller.signal,
      );
      let terminal = false;
      const outcome = session.result.catch((error: unknown) => {
        terminal = true;
        return error;
      });
      const events: HarnessEvent[] = [];
      const drained = (async () => {
        for await (const event of session.events) events.push(event);
      })();
      await ready;
      const command = runner.mock.calls.at(-1)?.[0];
      expect(command).toMatchObject({ timeoutMs: null, cwd: 'synthetic-workspace' });
      const removed = vi.spyOn(command!.signal, 'removeEventListener');
      expect(
        runner.mock.calls.map(([call]) =>
          call.args.includes('--version')
            ? 'version'
            : call.args.includes('--help')
              ? 'help'
              : call.args.includes('auth')
                ? 'auth'
                : 'turn',
        ),
      ).toEqual(['version', 'help', 'auth', 'turn']);
      await vi.advanceTimersByTimeAsync(999);
      expect(terminal).toBe(false);
      await vi.advanceTimersByTimeAsync(1);
      // A finite liveness oracle: the exact old source fails here, rather than hanging this test.
      expect(terminal).toBe(true);
      const failure = {
        code: 'HARNESS_TURN_FAILED',
        message:
          "Claude could not be started (ENOENT); check the Claude executable's path and permissions and the working directory",
        retriable: false,
      };
      expect(await outcome).toMatchObject(failure);
      await expect(session.sessionId).rejects.toMatchObject(failure);
      await drained;
      expect(events).toEqual([
        { type: 'error', ...failure, submission: 'definitely-not-submitted' },
      ]);
      const processResult = await runner.mock.results.at(-1)?.value;
      expect(processResult).toEqual({
        exitCode: null,
        stdout: '',
        timedOut: false,
        aborted: false,
        overflow: false,
        spawnCode: 'ENOENT',
      });
      const bytes = JSON.stringify({ events, processResult });
      expect(controller.signal.aborted).toBe(false);
      expect(removed).toHaveBeenCalledWith('abort', expect.any(Function));
      expect(vi.getTimerCount()).toBe(0);
      expect(killTree).not.toHaveBeenCalled();
      if (late === 'success') release(fileStats);
      else reject(Object.assign(new Error('PRIVATE_FS_BODY'), { code: 'ENOENT' }));
      await vi.advanceTimersByTimeAsync(0);
      expect(JSON.stringify({ events, processResult })).toBe(bytes);
      expect(stat).toHaveBeenCalledExactlyOnceWith('synthetic-workspace');
      expect(runner).toHaveBeenCalledTimes(4);
      expect(vi.getTimerCount()).toBe(0);
      expect(JSON.stringify(events)).not.toContain('PRIVATE');
    },
  );
  it.each([
    ['stdout', 1],
    ['stdout', null],
    ['stderr', 1],
    ['stderr', null],
  ] as const)(
    'keeps recognised auth stderr from signing out a check whose %s failed (close %s)',
    async (stream, code) => {
      scriptChecks((scripted) => {
        scripted.stderr?.emit('data', Buffer.from(diagnosis));
        scripted.stdout?.emit(
          'data',
          Buffer.from('{"authMethod":"claude.ai","email":"PRIVATE_STDOUT_BODY'),
        );
        scripted[stream]?.emit(
          'error',
          Object.assign(new Error('PRIVATE_PIPE_BODY'), { code: 'EPIPE' }),
        );
        scripted.emit('close', code);
      });
      const facts = await new ClaudeHarness({
        platform: 'win32',
        binary: 'synthetic-cli',
      }).preflight();
      expect(facts).toMatchObject({
        state: 'unknown',
        ok: false,
        version: '2.1.285',
        problems: [
          'Claude CLI check output could not be read. Check that the Claude CLI starts and responds, then retry preflight.',
        ],
      });
      expect(facts).not.toHaveProperty('authenticated');
      expect(killTree).toHaveBeenCalledTimes(1);
      expect(JSON.stringify(facts)).not.toContain('PRIVATE');
    },
  );
  it('still signs out on the same recognised auth stderr when the check output was complete', async () => {
    scriptChecks((scripted) => {
      scripted.stderr?.emit('data', Buffer.from(diagnosis));
      scripted.emit('close', 1);
    });
    const facts = await new ClaudeHarness({
      platform: 'win32',
      binary: 'synthetic-cli',
    }).preflight();
    expect(facts).toMatchObject({
      state: 'auth',
      ok: false,
      authenticated: false,
      problems: [
        'Claude sign-in is missing or invalid. Run claude auth login, then retry preflight.',
      ],
    });
    expect(killTree).not.toHaveBeenCalled();
    expect(JSON.stringify(facts)).not.toContain('PRIVATE');
  });
});

